  "event_type": "decision",
  "scheduled_pt_ms": 2100000,
  "duration_ms": 60000,
  "dependencies": ["evt-t7"],
  "triggered_issues": [
    "iss-air-threat"
  ],
  "target_roles": ["aawo", "eo"],
  "role_descriptions": {
    "aawo": "Report via MTC (C2 system): Hostile aircraft approaching area (ETA: 15 min).",
